import asyncio
import hashlib
import hmac
import os
import re
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple


@dataclass
class User:
    username: str
    role: str  # 'admin', 'moderator', 'user'
    session_token: str


@dataclass
class ChatRoom:
    name: str
    members: list = field(default_factory=list)
    messages: list = field(default_factory=list)
    admin_only: bool = False


class HTTPParser:
    """Minimal HTTP/1.1 parser for the chat server's internal proxy layer."""

    @staticmethod
    def parse_headers(raw_data: bytes) -> Tuple[Dict[str, str], bytes]:
        """Parse HTTP headers, return headers dict and body bytes."""
        header_end = raw_data.find(b"\r\n\r\n")
        if header_end == -1:
            return {}, b""

        header_section = raw_data[:header_end].decode('latin-1')
        body = raw_data[header_end + 4:]

        headers = {}
        lines = header_section.split("\r\n")
        # First line is request line
        if lines:
            headers['_request_line'] = lines[0]

        for line in lines[1:]:
            if ':' in line:
                key, value = line.split(':', 1)
                # RFC 7230: field names are case-insensitive
                headers[key.strip().lower()] = value.strip()

        return headers, body

    @staticmethod
    def determine_body_length(headers: Dict[str, str]) -> int:
        """Determine message body length per RFC 7230 Section 3.3.3.

        Priority: Transfer-Encoding takes precedence over Content-Length.
        However, for simplicity in this chat server, we handle both.
        """
        if 'transfer-encoding' in headers:
            te = headers['transfer-encoding'].lower()
            if 'chunked' in te:
                return -1  # Signal chunked encoding

        if 'content-length' in headers:
            try:
                return int(headers['content-length'])
            except ValueError:
                return 0
        return 0

    @staticmethod
    def decode_chunked_body(body: bytes) -> bytes:
        """Decode a chunked transfer-encoded body."""
        result = b""
        remaining = body
        while remaining:
            line_end = remaining.find(b"\r\n")
            if line_end == -1:
                break
            chunk_size_str = remaining[:line_end].decode('latin-1').strip()
            # Handle chunk extensions (ignore them)
            if ';' in chunk_size_str:
                chunk_size_str = chunk_size_str.split(';')[0]
            try:
                chunk_size = int(chunk_size_str, 16)
            except ValueError:
                break
            if chunk_size == 0:
                break
            chunk_start = line_end + 2
            chunk_data = remaining[chunk_start:chunk_start + chunk_size]
            result += chunk_data
            remaining = remaining[chunk_start + chunk_size + 2:]
        return result


class ChatServer:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.rooms: Dict[str, ChatRoom] = {
            'general': ChatRoom(name='general'),
            'admin-channel': ChatRoom(name='admin-channel', admin_only=True)
        }
        self.sessions: Dict[str, User] = {}
        self._setup_default_users()

    def _setup_default_users(self):
        admin = User(username='admin', role='admin', session_token=self._gen_token())
        guest = User(username='guest', role='user', session_token=self._gen_token())
        self.users['admin'] = admin
        self.users['guest'] = guest
        self.sessions[admin.session_token] = admin
        self.sessions[guest.session_token] = guest

    def _gen_token(self) -> str:
        return hashlib.sha256(os.urandom(32)).hexdigest()

    def authenticate(self, token: str) -> Optional[User]:
        return self.sessions.get(token)

    def authorize_room_access(self, user: User, room_name: str) -> bool:
        room = self.rooms.get(room_name)
        if not room:
            return False
        if room.admin_only and user.role != 'admin':
            return False
        return True

    def post_message(self, user: User, room_name: str, message: str) -> str:
        if not self.authorize_room_access(user, room_name):
            return '{"error": "access_denied"}'
        self.rooms[room_name].messages.append({
            'user': user.username,
            'message': message
        })
        return '{"status": "ok"}'

    def get_messages(self, user: User, room_name: str) -> str:
        if not self.authorize_room_access(user, room_name):
            return '{"error": "access_denied"}'
        msgs = self.rooms[room_name].messages[-50:]
        return str(msgs)


class RequestHandler:
    """Handles parsed HTTP requests for the chat server."""

    def __init__(self, server: ChatServer):
        self.server = server
        self.parser = HTTPParser()

    def handle_raw_data(self, raw_data: bytes) -> list:
        """Process raw TCP data that may contain multiple pipelined requests.

        Returns list of response strings.
        """
        responses = []
        remaining = raw_data

        while remaining:
            headers, body_start = self.parser.parse_headers(remaining)
            if not headers:
                break

            body_length = self.parser.determine_body_length(headers)

            if body_length == -1:
                # Chunked encoding
                body = self.parser.decode_chunked_body(body_start)
                # Find end of chunked body in raw stream to advance pointer
                # Look for 0\r\n\r\n terminator
                term_pos = remaining.find(b"0\r\n\r\n")
                if term_pos != -1:
                    next_start = term_pos + 5
                else:
                    next_start = len(remaining)
                remaining = remaining[next_start:]
            elif body_length > 0:
                header_end = remaining.find(b"\r\n\r\n") + 4
                body = remaining[header_end:header_end + body_length]
                remaining = remaining[header_end + body_length:]
            else:
                header_end = remaining.find(b"\r\n\r\n") + 4
                body = b""
                remaining = remaining[header_end:]

            response = self._dispatch(headers, body)
            responses.append(response)

        return responses

    def _dispatch(self, headers: Dict[str, str], body: bytes) -> str:
        request_line = headers.get('_request_line', '')
        parts = request_line.split(' ')
        if len(parts) < 2:
            return 'HTTP/1.1 400 Bad Request\r\n\r\n'

        method, path = parts[0], parts[1]
        token = headers.get('x-auth-token', '')
        user = self.server.authenticate(token)

        if path.startswith('/chat/') and method == 'POST':
            if not user:
                return 'HTTP/1.1 401 Unauthorized\r\n\r\n{"error": "auth_required"}'
            room_name = path[6:]  # strip '/chat/'
            message = body.decode('utf-8', errors='replace')
            result = self.server.post_message(user, room_name, message)
            return f'HTTP/1.1 200 OK\r\n\r\n{result}'

        elif path.startswith('/chat/') and method == 'GET':
            if not user:
                return 'HTTP/1.1 401 Unauthorized\r\n\r\n{"error": "auth_required"}'
            room_name = path[6:]
            result = self.server.get_messages(user, room_name)
            return f'HTTP/1.1 200 OK\r\n\r\n{result}'

        elif path == '/health':
            return 'HTTP/1.1 200 OK\r\n\r\n{"status": "healthy"}'

        return 'HTTP/1.1 404 Not Found\r\n\r\n'


async def handle_connection(reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
    handler = RequestHandler(chat_server)
    try:
        while True:
            data = await asyncio.wait_for(reader.read(8192), timeout=30.0)
            if not data:
                break
            responses = handler.handle_raw_data(data)
            for resp in responses:
                writer.write(resp.encode('utf-8'))
                await writer.drain()
    except (asyncio.TimeoutError, ConnectionResetError):
        pass
    finally:
        writer.close()


chat_server = ChatServer()


async def main():
    server = await asyncio.start_server(handle_connection, '127.0.0.1', 8080)
    async with server:
        await server.serve_forever()


if __name__ == '__main__':
    asyncio.run(main())
